    ; __append("\r\n\r\n<!-- ABOUT HERO -->\r\n<section class=\"about-hero\" style=\"margin-top: 50px;\">\r\n    <div class=\"about-container\">\r\n\r\n        <div class=\"about-content\">\r\n            <span class=\"about-tag\">ABOUT FRIENDS' ENGLISH ACADEMY</span>\r\n\r\n            <h1>\r\n                Where Learning Meets\r\n                <span>Friendship.</span>\r\n            </h1>\r\n\r\n            <p>\r\n                At Friends' English Academy, we believe that learning English\r\n                should be simple, practical and enjoyable. Our goal is to help\r\n                learners communicate confidently and achieve their personal,\r\n                academic and professional goals.\r\n            </p>\r\n\r\n            <a href=\"/contact\" class=\"about-btn\">\r\n                Join Our Academy\r\n                <i class=\"fa-solid fa-arrow-right\"></i>\r\n            </a>\r\n        </div>\r\n\r\n        <div class=\"about-hero-image\">\r\n            <!-- Add your academy image here -->\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- WHO WE ARE -->\r\n<section class=\"about-intro\">\r\n    <div class=\"about-container intro-grid\">\r\n\r\n        <div class=\"intro-image\">\r\n            <!-- Add classroom or student image here -->\r\n        </div>\r\n\r\n        <div class=\"intro-content\">\r\n            <span class=\"about-label\">WHO WE ARE</span>\r\n\r\n            <h2>Helping You Speak English With Confidence</h2>\r\n\r\n            <p>\r\n                Friends' English Academy is dedicated to developing English\r\n                language skills through structured learning, practical\r\n                activities and regular speaking practice.\r\n            </p>\r\n\r\n            <p>\r\n                We follow the CEFR (Common European Framework of Reference\r\n                for Languages), covering all six levels from A1 to C2.\r\n                Whether you are a beginner or an advanced learner, we help\r\n                you improve step by step.\r\n            </p>\r\n\r\n            <div class=\"about-highlight\">\r\n                <i class=\"fa-solid fa-graduation-cap\"></i>\r\n                <div>\r\n                    <h4>Learn at Your Own Level</h4>\r\n                    <p>From basic English to advanced communication.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- MISSION AND VISION -->\r\n<section class=\"mission-section\">\r\n    <div class=\"about-section-heading\">\r\n        <span>OUR PURPOSE</span>\r\n        <h2>Our Mission & Vision</h2>\r\n        <p>Building confidence through effective English learning.</p>\r\n    </div>\r\n\r\n    <div class=\"mission-container\">\r\n\r\n        <div class=\"mission-card\">\r\n            <div class=\"mission-icon\">\r\n                <i class=\"fa-solid fa-bullseye\"></i>\r\n            </div>\r\n\r\n            <h3>Our Mission</h3>\r\n\r\n            <p>\r\n                To provide quality English education through practical\r\n                learning, interactive sessions and regular speaking practice,\r\n                helping learners communicate confidently in everyday life.\r\n            </p>\r\n        </div>\r\n\r\n        <div class=\"mission-card\">\r\n            <div class=\"mission-icon\">\r\n                <i class=\"fa-solid fa-eye\"></i>\r\n            </div>\r\n\r\n            <h3>Our Vision</h3>\r\n\r\n            <p>\r\n                To create a supportive learning environment where every\r\n                student can develop strong communication skills and become\r\n                confident in English.\r\n            </p>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- WHY CHOOSE US -->\r\n<section class=\"why-about\">\r\n    <div class=\"about-section-heading\">\r\n        <span>WHY CHOOSE US</span>\r\n        <h2>Learn Better. Speak Better. Grow Better.</h2>\r\n        <p>We focus on practical English learning and student development.</p>\r\n    </div>\r\n\r\n    <div class=\"why-grid\">\r\n\r\n        <div class=\"why-card\">\r\n            <i class=\"fa-solid fa-book-open\"></i>\r\n            <h3>CEFR-Based Curriculum</h3>\r\n            <p>Structured English learning from A1 to C2 levels.</p>\r\n        </div>\r\n\r\n        <div class=\"why-card\">\r\n            <i class=\"fa-solid fa-comments\"></i>\r\n            <h3>Daily Speaking Practice</h3>\r\n            <p>Improve fluency through conversations and interactive activities.</p>\r\n        </div>\r\n\r\n        <div class=\"why-card\">\r\n            <i class=\"fa-solid fa-users\"></i>\r\n            <h3>Small Batches</h3>\r\n            <p>Maximum 15–18 learners for better attention and guidance.</p>\r\n        </div>\r\n\r\n        <div class=\"why-card\">\r\n            <i class=\"fa-solid fa-chalkboard-user\"></i>\r\n            <h3>Experienced Trainers</h3>\r\n            <p>Learn with qualified and experienced English trainers.</p>\r\n        </div>\r\n\r\n        <div class=\"why-card\">\r\n            <i class=\"fa-solid fa-clipboard-check\"></i>\r\n            <h3>Regular Assessments</h3>\r\n            <p>Track your learning progress through tests and feedback.</p>\r\n        </div>\r\n\r\n        <div class=\"why-card\">\r\n            <i class=\"fa-solid fa-certificate\"></i>\r\n            <h3>Course Certificate</h3>\r\n            <p>Receive a course completion certificate after completing the programme.</p>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- TEACHING METHOD -->\r\n<section class=\"method-section\">\r\n    <div class=\"about-container method-grid\">\r\n\r\n        <div class=\"method-content\">\r\n            <span class=\"about-label\">OUR TEACHING APPROACH</span>\r\n\r\n            <h2>English Learning That Goes Beyond Textbooks</h2>\r\n\r\n            <p>\r\n                We believe that the best way to learn English is to use it.\r\n                Our teaching approach combines grammar, listening, reading,\r\n                writing and practical speaking activities.\r\n            </p>\r\n\r\n            <ul>\r\n                <li><i class=\"fa-solid fa-check-circle\"></i> Cambridge and Oxford-inspired teaching methodologies</li>\r\n                <li><i class=\"fa-solid fa-check-circle\"></i> Real-life conversation practice</li>\r\n                <li><i class=\"fa-solid fa-check-circle\"></i> Group discussions and presentations</li>\r\n                <li><i class=\"fa-solid fa-check-circle\"></i> Regular feedback and doubt-solving</li>\r\n                <li><i class=\"fa-solid fa-check-circle\"></i> Vocabulary and pronunciation development</li>\r\n            </ul>\r\n        </div>\r\n\r\n        <div class=\"method-image\">\r\n             <img src=\"/images/book.png\" alt=\"Book image\">\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- FOUNDER -->\r\n<section class=\"founder-section\">\r\n    <div class=\"about-section-heading\">\r\n        <span>MEET OUR TRAINER</span>\r\n        <h2>Guidance That Makes a Difference</h2>\r\n    </div>\r\n\r\n    <div class=\"founder-card\">\r\n\r\n        <div class=\"founder-image\">\r\n            <img src=\"/images/founder.png\" alt=\"founder image\">\r\n        </div>\r\n\r\n        <div class=\"founder-content\">\r\n            <span class=\"about-label\">FOUNDER & LEAD TRAINER</span>\r\n\r\n            <h2>Iftekhar R. Shaikh</h2>\r\n\r\n            <h4>English Language Trainer</h4>\r\n\r\n            <p>\r\n                With over 5 years of experience in English training and\r\n                student counselling, our lead trainer focuses on helping\r\n                learners improve their communication skills and build\r\n                confidence.\r\n            </p>\r\n\r\n            <div class=\"experience-badge\">\r\n                <i class=\"fa-solid fa-award\"></i>\r\n                5+ Years of Experience\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- FLUENCY CLUB -->\r\n<section class=\"fluency-section\">\r\n    <div class=\"fluency-container\">\r\n\r\n        <div class=\"fluency-image\">\r\n            <!-- Add group discussion / fluency club image here -->\r\n        </div>\r\n\r\n        <div class=\"fluency-content\">\r\n            <span class=\"about-label\">EVERY SATURDAY</span>\r\n\r\n            <h2>Friends' Fluency Club</h2>\r\n\r\n            <p>\r\n                A weekly speaking session designed to help learners improve\r\n                fluency, build confidence and communicate effectively in English.\r\n            </p>\r\n\r\n            <ul>\r\n                <li>Group discussions</li>\r\n                <li>Role plays and speaking activities</li>\r\n                <li>Real-life communication practice</li>\r\n                <li>Supportive trainer feedback</li>\r\n            </ul>\r\n\r\n            <div class=\"free-session\">\r\n                <i class=\"fa-solid fa-gift\"></i>\r\n                Free Speaking Session – Open to All Learners\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- FACILITIES -->\r\n<section class=\"facilities-section\">\r\n    <div class=\"about-section-heading\">\r\n        <span>OUR FACILITIES</span>\r\n        <h2>A Comfortable Place to Learn</h2>\r\n    </div>\r\n\r\n    <div class=\"facilities-grid\">\r\n\r\n        <div class=\"facility-item\">\r\n            <i class=\"fa-solid fa-snowflake\"></i>\r\n            <h4>Air-Conditioned Classrooms</h4>\r\n        </div>\r\n\r\n        <div class=\"facility-item\">\r\n            <i class=\"fa-solid fa-book\"></i>\r\n            <h4>Printed Study Material</h4>\r\n        </div>\r\n\r\n        <div class=\"facility-item\">\r\n            <i class=\"fa-solid fa-wifi\"></i>\r\n            <h4>Complimentary Wi-Fi</h4>\r\n        </div>\r\n\r\n        <div class=\"facility-item\">\r\n            <i class=\"fa-brands fa-whatsapp\"></i>\r\n            <h4>WhatsApp Learning Support</h4>\r\n        </div>\r\n\r\n        <div class=\"facility-item\">\r\n            <i class=\"fa-solid fa-users\"></i>\r\n            <h4>Student-Friendly Environment</h4>\r\n        </div>\r\n\r\n        <div class=\"facility-item\">\r\n            <i class=\"fa-solid fa-glass-water\"></i>\r\n            <h4>Drinking Water Facility</h4>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- FINAL CTA -->\r\n<section class=\"about-cta\">\r\n    <h2>Ready to Improve Your English?</h2>\r\n\r\n    <p>\r\n        Take the first step towards better communication and a more confident future.\r\n    </p>\r\n\r\n    <a href=\"/contact\" class=\"about-btn\">\r\n        Contact Us Today\r\n        <i class=\"fa-solid fa-arrow-right\"></i>\r\n    </a>\r\n</section>")
